const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const crater = ee.Geometry.Point([-155.283, 19.406]); // Halema'uma'u Crater
  const buffer = crater.buffer(1000); // 1km buffer around crater

  // July 20, 2025 at 10:44 am local time (HAST = UTC-10) = 20:44 UTC
  const targetDate = '2025-07-20';
  const startTime = ee.Date('2025-07-20T19:44:00'); // UTC: 1 hour before local time
  const endTime = ee.Date('2025-07-20T21:44:00');   // UTC: 1 hour after local time

  // 2. Data Acquisition - Try VIIRS thermal anomalies first
  let viirsCol = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
    .filterBounds(buffer)
    .filterDate(startTime, endTime);

  let viirsSize = viirsCol.size().getInfo();
  console.log(`VIIRS Images: ${viirsSize}`);

  let result = null;
  let collectionName = '';

  if (viirsSize > 0) {
    // Use VIIRS data
    collectionName = 'VIIRS';
    const viirsImg = viirsCol.first();

    // Band info: 'MaxFRP' = Fire Radiative Power, 'Confidence' = detection confidence
    // Confidence values: 0-3 (low), 4-6 (nominal), 7-9 (high)
    const highConfidence = viirsImg.select('Confidence').gte(7); // High confidence mask

    // Count high-confidence thermal anomaly pixels in buffer
    const stats = highConfidence.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: buffer,
      scale: 375, // VIIRS resolution
      maxPixels: 1e9
    });

    const highConfCount = stats.get('Confidence').getInfo();
    console.log(`High-confidence thermal pixels: ${highConfCount}`);

    // Also check total FRP for magnitude
    const frpStats = viirsImg.select('MaxFRP').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: buffer,
      scale: 375,
      maxPixels: 1e9
    });

    const meanFRP = frpStats.get('MaxFRP').getInfo();
    console.log(`Mean Fire Radiative Power: ${meanFRP ? meanFRP.toFixed(2) : 'null'}`);

    result = highConfCount;

  } else {
    // Try MODIS as fallback
    console.log('No VIIRS data, trying MODIS...');

    // Check both Terra (MOD14A1) and Aqua (MYD14A1)
    const modisTerra = ee.ImageCollection('MODIS/061/MOD14A1')
      .filterBounds(buffer)
      .filterDate(startTime, endTime);

    const modisAqua = ee.ImageCollection('MODIS/061/MYD14A1')
      .filterBounds(buffer)
      .filterDate(startTime, endTime);

    const terraSize = modisTerra.size().getInfo();
    const aquaSize = modisAqua.size().getInfo();

    console.log(`MODIS Terra: ${terraSize}, Aqua: ${aquaSize}`);

    let modisCol = modisTerra.merge(modisAqua);
    const totalModis = terraSize + aquaSize;

    if (totalModis > 0) {
      collectionName = 'MODIS';
      const modisImg = modisCol.mosaic(); // Combine available overpasses

      // MODIS fire mask: values 7,8,9 = fire (high confidence)
      const fireMask = modisImg.select('FireMask').gte(7);

      const stats = fireMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: buffer,
        scale: 1000, // MODIS resolution
        maxPixels: 1e9
      });

      const fireCount = stats.get('FireMask').getInfo();
      console.log(`MODIS fire pixels: ${fireCount}`);

      result = fireCount;
    }
  }

  // 3. Validation & Final Answer
  if (result === null) {
    // No data in any collection
    console.log('No thermal anomaly data available for specified time/location.');
    console.log('<answer>C1</answer>');
  } else if (result === undefined || isNaN(result)) {
    // Calculation failed
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
  } else if (result === 0) {
    // Valid zero - no thermal anomalies detected
    console.log(`No thermal anomalies detected in ${collectionName} data.`);
    console.log('<answer>B</answer>');
  } else if (result > 0) {
    // Thermal anomalies detected
    console.log(`Detected ${result} thermal anomaly pixel(s) in ${collectionName} data.`);
    console.log('<answer>A</answer>');
  } else {
    // Unexpected case
    console.log('<answer>C3</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
